const words = puzzle.split(/==|===/).map(s => s.trim()).filter(Boolean);
const left = words[0].split(/\s+/).map(s => s.replace(/\s+/g, ''));
const right = words[1].split(/\s+/).map(s => s.replace(/\s+/g, ''));
const letters = [...new Set([...left, ...right].split(''))];
if (letters.length > 10) return undefined;
const n = letters.length;
const used = new Array(10).fill(false);
const perm = new Array(n);
const wordLen = left.map(w => w.length);
const rightLen = right.map(w => w.length);
const leading = new Set(left.map((_, i) => letters.indexOf(left[i][0])));
leading.add(right.map((_, i) => letters.indexOf(right[i][0])));
const wordMap = new Map();
for (const w of left) wordMap.set(w, []);
for (const w of right) wordMap.set(w, []);
const wordIndices = new Map();
for (let i = 0; i < left.length; i++) wordIndices.set(left[i], i);
for (let i = 0; i < right.length; i++) wordIndices.set(right[i], i);
const wordValues = new Array(left.length + right.length).fill(0);
const wordSigns = new Array(left.length + right.length).fill(1);
for (let i = 0; i < left.length; i++) wordSigns[i] = 1;
for (let i = 0; i < right.length; i++) wordSigns[i + left.length] = 1;
const wordDigits = new Array(left.length + right.length);
for (let i = 0; i < left.length; i++) {
  const w = left[i];
  wordDigits[i] = [];
  for (let j = 0; j < w.length; j++) wordDigits[i].push(wordMap.get(w)[j]);
}
for (let i = 0; i < right.length; i++) {
  const w = right[i];
  wordDigits[i + left.length] = [];
  for (let j = 0; j < w.length; j++) wordDigits[i + left.length].push(wordMap.get(w)[j]);
}
const wordLens = new Array(left.length + right.length);
for (let i = 0; i < left.length; i++) wordLens[i] = left[i].length;
for (let i = 0; i < right.length; i++) wordLens[i + left.length] = right[i].length;
const maxLen = Math.max(...wordLens);
const carry = new Array(maxLen + 1).fill(0);
const result = new Array(10).fill(0);
const solution = new Map();
const backtrack = (idx) => {
  if (idx === n) {
    let c = 0;
    for (let i = 0; i < left.length; i++) {
      let val = 0;
      for (let j = 0; j < left[i].length; j++) {
        val = val * 10 + solution.get(letters[left[i][j]]);
      }
      c += val;
    }
    for (let i = 0; i < right.length; i++) {
      let val = 0;
      for (let j = 0; j < right[i].length; j++) {
        val = val * 10 + solution.get(letters[right[i][j]]);
      }
      c -= val;
    }
    if (c === 0) return true;
    return false;
  }
  const letter = letters[idx];
  for (let d = 0; d <= 9; d++) {
    if (used[d]) continue;
    if (leading.has(idx) && d === 0) continue;
    used[d] = true;
    solution.set(letter, d);
    if (backtrack(idx + 1)) return true;
    used[d] = false;
    solution.delete(letter);
  }
  return false;
};
backtrack(0);
const ans = {};
for (const [k, v] of solution) ans[k] = v;
return ans;

